const todayStudentExams = `-- name: TodayStudentExams :many
select e.id, e.course_id, e.title, e.opens_at, e.closes_at, e.duration_minutes, a.status as attempt_status, a.deadline_at as attempt_deadline
from exams e
left join exam_attempts a on a.course_id = e.course_id and a.exam_id = e.id and a.student_id = $1
where e.course_id = any($2::text[]::uuid[])
  and e.status in ('SCHEDULED', 'OPEN')
  and e.closes_at > $3::timestamptz
  and e.opens_at <= $4::timestamptz
  and (a.id is null or (a.status = 'IN_PROGRESS' and a.deadline_at > $3::timestamptz))
order by e.opens_at, e.id
`

