// "Hôm nay" của sinh viên: bài SCHEDULED / OPEN còn hạn, mở trong `horizon`, chưa có lượt làm hoặc lượt còn đang làm — MỘT truy vấn cho mọi lớp.
func (q *Queries) TodayStudentExams(ctx context.Context, arg TodayStudentExamsParams) ([]TodayStudentExamsRow, error) {
	rows, err := q.db.Query(ctx, todayStudentExams,
		arg.UserID,
		arg.CourseIds,
		arg.Now,
		arg.Horizon,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TodayStudentExamsRow{}
	for rows.Next() {
		var i TodayStudentExamsRow
		if err := rows.Scan(
			&i.ID,
			&i.CourseID,
			&i.Title,
			&i.OpensAt,
			&i.ClosesAt,
			&i.DurationMinutes,
			&i.AttemptStatus,
			&i.AttemptDeadline,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
